```python
def equals(self, other):
    self_axes, other_axes = self.axes, other.axes
    if len(self_axes) != len(other_axes):
        return False
    if not all(ax1.equals(ax2) for ax1, ax2 in zip(self_axes, other_axes)):
        return False
    self._consolidate_inplace()
    other._consolidate_inplace()

    # Here we need to check the blocks' data types and the values to ensure they are not only sorted by their dtype
    if len(self.blocks) != len(other.blocks):
        return False

    def canonicalize(block):
        return (block.dtype.name, list(block.mgr_locs))

    self_blocks = sorted(self.blocks, key=canonicalize)
    other_blocks = sorted(other.blocks, key=canonicalize)

    # Compare block data and types, we should ensure the types and values match exactly
    return all(block.equals(oblock) for block, oblock in zip(self_blocks, other_blocks)) and all(
        block.dtype == oblock.dtype and block.values.flatten().tolist() == oblock.values.flatten().tolist()
        for block, oblock in zip(self_blocks, other_blocks)
    )
```

